-- Update 20: menu card without food names (kitchen philosophy) + middle fanned photo = glasses at the bar
UPDATE "site_content" SET "data" = "data" || '{"cardKicker": "Our kitchen philosophy", "highlights": [{"label": "Every day", "title": "Sourced", "text": "From local growers, farms and suppliers across Cyprus"}, {"label": "From scratch", "title": "Crafted", "text": "Prepared by hand by our kitchen team, plate by plate"}, {"label": "All year", "title": "Seasonal", "text": "A menu that changes with the island’s seasons"}, {"label": "Until late", "title": "Shared", "text": "Made for long tables, good company and sea views"}]}'::jsonb WHERE "key" = 'home.menu';--> statement-breakpoint
UPDATE "site_content" SET "data" = jsonb_set("data", '{fan}', (SELECT jsonb_agg(CASE WHEN e->>'image' = '/images/ig/fan-entrance.webp' THEN e || '{"image": "/images/ig/bar-glasses.webp", "alt": "Glasses at the Ammos bar with the sea behind"}'::jsonb ELSE e END ORDER BY o) FROM jsonb_array_elements("data"->'fan') WITH ORDINALITY AS t(e, o))) WHERE "key" = 'home.story' AND jsonb_typeof("data"->'fan') = 'array' AND jsonb_array_length("data"->'fan') > 0;
